<?php
namespace App\Http\Middleware;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class SecurityHeaders{public function handle(Request $request,Closure $next):Response{$response=$next($request);$response->headers->set('X-Content-Type-Options','nosniff');$response->headers->set('X-Frame-Options','SAMEORIGIN');$response->headers->set('Referrer-Policy','strict-origin-when-cross-origin');$response->headers->set('Permissions-Policy','camera=(self), geolocation=(self), microphone=()');$response->headers->set('Content-Security-Policy',"default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'self'; form-action 'self' https://checkout.wompi.co; script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://checkout.wompi.co; style-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com; img-src 'self' data: blob: https://*.tile.openstreetmap.org; font-src 'self' data:; connect-src 'self' https://router.project-osrm.org https://api-colombia.com wss: ws:; frame-src https://checkout.wompi.co");if($request->isSecure())$response->headers->set('Strict-Transport-Security','max-age=31536000; includeSubDomains');return $response;}}